export function CoinFlipWorkspace({ locale = "ru" }: { locale?: "ru" | "tr" | "pl" }) {
  const [count, setCount] = useState(1);
  const [flips, setFlips] = useState<number[]>([]);
  const [error, setError] = useState("");
  const labels = locale === "pl"
    ? { count: "Liczba rzut\u00F3w", again: "Rzu\u0107 ponownie", flip: "Rzu\u0107 monet\u0105", result: "Wynik", heads: "Orze\u0142", tails: "Reszka", invalid: "Wpisz liczb\u0119 od 1 do 1000." }
    : locale === "tr"
    ? { count: "Yaz? tura say?s?", again: "Tekrar at", flip: "Yaz? tura at", result: "Sonu?", heads: "Yaz?", tails: "Tura", invalid: "1 ile 1000 aras?nda bir say? girin." }
    : { count: "?????????? ???????", again: "??????? ???", flip: "??????? ??????", result: "?????????", heads: "????", tails: "?????", invalid: "??????? ????? ?? 1 ?? 1000." };
  function flip() {
    if (!Number.isSafeInteger(count) || count < 1 || count > 1000) { setError(labels.invalid); return; }
    setFlips(Array.from({ length: count }, () => randomInt(0, 1)));
    setError("");
  }
  const heads = flips.filter((side) => side === 0).length;
  const tails = flips.length - heads;
  return <section className="rounded-3xl border bg-white p-5 shadow-sm sm:p-7">
    <label className="block text-sm font-semibold">{labels.count}<input type="number" min="1" max="1000" value={count} onChange={(event) => setCount(Number(event.target.value))} className="mt-2 block w-full rounded-xl border p-3 sm:max-w-xs" /></label>
    <button type="button" onClick={flip} className="mt-5 min-h-12 rounded-xl bg-indigo-600 px-5 font-semibold text-white">{flips.length ? labels.again : labels.flip}</button>
    {error && <p role="alert" className="mt-3 text-sm text-rose-700">{error}</p>}
    {flips.length > 0 && <section className="mt-5 rounded-2xl bg-slate-50 p-4"><h3 className="font-semibold">{labels.result}</h3><dl className="mt-3 grid grid-cols-2 gap-3"><div className="rounded-xl bg-white p-3"><dt className="text-sm text-slate-500">{labels.heads}</dt><dd className="mt-1 text-xl font-bold">{heads}</dd></div><div className="rounded-xl bg-white p-3"><dt className="text-sm text-slate-500">{labels.tails}</dt><dd className="mt-1 text-xl font-bold">{tails}</dd></div></dl><p className="mt-3 break-words text-sm text-slate-600">{flips.map((side) => side === 0 ? labels.heads : labels.tails).join(" ? ")}</p></section>}
  </section>;
}
